#include "ui_objects.h"
#include "aic_ui.h"
#include "ui_util.h"
#include "aic_core.h"

#include <sys/stat.h>
#include <unistd.h>

#include "lv_aic_player.h"

#define MIPI_SD_VIDEO "/sdcard/lvgl_data/video/putao_publicity_720x1280_jpeg_aac.mp4"

/* 1：正在经 SDIO 灌 8800 固件。这段读 SD 上的视频会把 dbg mem 读拖到 5 秒超时。 */
extern int aic8800_fwload_busy(void);

/* mipi_video_try_cb()：LVGL 定时器回调。文件在就播，但要等 WiFi 固件灌完。
   不在就过 200ms 再看，最多 40 次。固件最多再等 60 秒。不能在 screen_create() 里睡。 */
static void mipi_video_try_cb(lv_timer_t *timer)
{
    screen_t *scr = screen_get(&ui_manager);
    struct stat st;
    static int tries;
    static int fw_waits;

    if (!scr || !scr->player_1) {
        lv_timer_del(timer);
        return;
    }

    if (aic8800_fwload_busy()) {
        if (++fw_waits < 300)
            return;
        pr_warn("mipi video: wifi fwload still busy\n");
    }

    if (stat(MIPI_SD_VIDEO, &st) != 0) {
        if (++tries >= 40) {
            pr_err("mipi video missing %s\n", MIPI_SD_VIDEO);
            lv_timer_del(timer);
        }
        return;
    }

    lv_timer_del(timer);
    pr_info("mipi video %s size %ld\n", MIPI_SD_VIDEO, (long)st.st_size);

    if (lv_aic_player_set_src(scr->player_1, MIPI_SD_VIDEO) != LV_RES_OK)
        pr_err("mipi video set_src failed\n");
    else
        pr_info("mipi video set_src ok\n");

    lv_aic_player_set_auto_restart(scr->player_1, true);
    lv_aic_player_set_cmd(scr->player_1, LV_AIC_PLAYER_CMD_START, NULL);
    pr_info("mipi video start\n");
}

void screen_create(ui_manager_t *ui)
{
    screen_t *scr = screen_get(ui);

    if (!ui->auto_del && scr->obj) {
        return;
    }

    scr->obj = lv_obj_create(NULL);
    lv_obj_set_scrollbar_mode(scr->obj, LV_SCROLLBAR_MODE_OFF);
    lv_obj_set_style_bg_opa(scr->obj, LV_OPA_TRANSP, LV_PART_MAIN | LV_STATE_DEFAULT);

    scr->player_1 = lv_aic_player_create(scr->obj);
    lv_obj_set_pos(scr->player_1, 0, 0);
    lv_obj_set_size(scr->player_1, 720, 1280);
    /* 必须在 set_src 之前。LAYER_VIDEO 把帧送到 AICFB_LAYER_TYPE_VIDEO，和 D213 点亮走的是同一层。 */
    lv_aic_player_set_draw_layer(scr->player_1, LV_AIC_PLAYER_LAYER_VIDEO);

    /* lv_timer_create() 建一个 200ms 的定时器，回调是 mipi_video_try_cb()。
       第一次触发在 ui_init() 返回、lv_task_handler() 已经画过 QSPI 之后。 */
    lv_timer_create(mipi_video_try_cb, 200, NULL);
}
